using System;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;
using System.IO;

namespace Ara {
 public static class FastTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static State New(){var s=State.New();GridEngine.Ensure(s,s.GetDay(DateTime.Today));return s;}
  static void OldMeal(State s){s.Days[0].Records.Add(new CellBlock{Id="old-meal",Start=DateTime.Today.AddHours(11),Count=4,Name="점심",Category="식사",MealId="b6",Score=2});}
  public static void Run(Action<string,Action> check,string dir){
   check("wake: generating at 15:00 preserves old 11:00 meal without blocking",()=>{var s=New();OldMeal(s);using(var f=new MainForm(new Store(Path.Combine(dir,"wake15.json")),s,true)){f.Show();Application.DoEvents();f.GenerateAt(DateTime.Today.AddHours(15));Assert(f.Day.Wake==DateTime.Today.AddHours(15)&&f.GridPlan.Blocks.Single(x=>x.MealId=="b1").Start==DateTime.Today.AddHours(15).AddMinutes(30),"new first meal");Assert(f.GridPlan.Blocks.Single(x=>x.MealId=="b16").End==DateTime.Today.AddDays(1).AddHours(6).AddMinutes(40),"next-day end");Assert(f.Day.Records.Single().Start==DateTime.Today.AddHours(11)&&GridEngine.Total(f.Day)==8,"old facts retained");f.Board.Jump(f.Day.Wake.AddHours(-1));using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,f.Size));image.Save(Path.Combine(dir,"wake15-smoke.png"));}f.Quit();}});
   check("wake: upper cell wake sets one marker and generates future plan",()=>{var s=New();OldMeal(s);using(var f=new MainForm(new Store(Path.Combine(dir,"wake-cell.json")),s,true)){f.Show();Application.DoEvents();f.ApplyCategory(new CellSelection{Lane=0,First=90,Last=95},"기상");Assert(f.Day.Wake==DateTime.Today.AddHours(15)&&f.Board.At(0,90).Category=="기상"&&f.Board.At(0,90).Count==1&&f.Board.At(0,93).MealId=="b1","wake and meal cells");Assert(f.Day.Records.Count==1&&f.Board.Selection.Count==1,"range becomes wake cell, actual history preserved");f.Quit();}});
   check("wake: actual wake cell preserves typed score and regenerates",()=>{var s=New();using(var f=new MainForm(new Store(Path.Combine(dir,"wake-actual.json")),s,true)){f.Show();Application.DoEvents();f.Board.SetSelection(new CellSelection{Lane=1,First=90,Last=90});f.ApplyQuickScore(5);f.ApplyCategory(f.Board.Selection,"기상");Assert(f.Day.Wake==DateTime.Today.AddHours(15)&&f.Day.Records.Single().Category=="기상"&&GridEngine.Total(f.Day)==5,"actual wake score");Assert(f.GridPlan.Blocks.Single(x=>x.MealId=="b6").Start==DateTime.Today.AddHours(19).AddMinutes(30),"second meal generated");f.Quit();}});
   check("wake: old meal does not consume the new routine meal or suppress reminders",()=>{var s=New();OldMeal(s);var d=s.Days[0];d.Wake=DateTime.Today.AddHours(15);d.GridBase=GridEngine.Generate(s,d);var p=GridEngine.Build(s,d);var current=p.Blocks.Single(x=>x.MealId=="b6");var record=new CellBlock{Id="new-meal",Start=current.Start,Count=3,Category="식사",Name="",Score=3};Assert(GridEngine.DetectMeal(d,p,record)=="b6","old meal excluded from used slots");Assert(!GridEngine.AsPlan(s,d,p).Slots.Single(x=>x.Block.Id==current.Id).Done,"reminder not suppressed");record.MealId="b6";d.Records.Add(record);GridEngine.Validate(d);Assert(GridEngine.Build(s,d).Blocks.Single(x=>x.MealId=="b6").Start==record.Start&&GridEngine.Total(d)==17,"old and new meal facts coexist");});
   check("keyboard: range digit keys save decimal scores with multi-digit entry",()=>{using(var f=new Form{Size=new Size(900,650)})using(var b=new TestBoard()){f.Controls.Add(b);f.Show();Application.DoEvents();b.SetData(DateTime.Today,new List<CellBlock>(),new List<CellBlock>());b.SimulateDrag(1,90,101,true);var records=new List<CellBlock>();b.ScoreRequested+=(s,e)=>GridEngine.SetScore(records,b.TimeAt(b.Selection.First),b.Selection.Count,e.Score);b.Press(Keys.D3);Assert(records.Sum(x=>x.Score*x.Count)==36,"3*12");b.Press(Keys.D0);Assert(records.Sum(x=>x.Score*x.Count)==360,"30*12");b.Press(Keys.Enter);b.Press(Keys.NumPad2);b.Press(Keys.Decimal);b.Press(Keys.NumPad5);Assert(records.Sum(x=>x.Score*x.Count)==30,"2.5*12");b.SetSelection(new CellSelection{Lane=0,First=90,Last=91});b.Press(Keys.D9);Assert(records.Sum(x=>x.Score*x.Count)==30,"upper ignored");f.Close();}});
   check("keyboard: scoring partial meals keeps outside scores and meal identity",()=>{var s=New();var d=s.Days[0];d.Records.Add(new CellBlock{Id="a",Start=d.Wake.AddMinutes(30),Count=3,Name="1끼니",Category="식사",MealId="b1",Score=1});GridEngine.SetScore(d.Records,d.Wake.AddMinutes(40),1,5);GridEngine.Validate(d);Assert(GridEngine.Total(d)==7&&d.Records.Count(x=>x.MealId=="b1")==1,"5+1+1");Assert(GridEngine.Build(s,d).Blocks.Single(x=>x.MealId=="b1").Start==d.Wake.AddMinutes(30),"anchor unchanged");});
   check("menu: reclick menu includes category, length, management and detail entry",()=>{var s=New();using(var f=new MainForm(new Store(Path.Combine(dir,"menu.json")),s,true)){f.Show();Application.DoEvents();var selected=new CellSelection{Lane=1,First=54,Last=65};f.Board.SetSelection(selected);using(var menu=f.CreateCategoryMenu(selected)){Assert(menu.Items.Count==GridEngine.Categories.Length+5&&menu.Items.Cast<ToolStripItem>().Any(x=>x.Text=="체크리스트")&&menu.Items[0].Text=="기상"&&menu.Items[menu.Items.Count-1].Text=="상세입력","minimal menu");menu.Show(f.Board,new Point(220,100));Application.DoEvents();using(var image=new Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(image,new Rectangle(Point.Empty,menu.Size));image.Save(Path.Combine(dir,"categories-smoke.png"));}menu.Close();((ToolStripMenuItem)menu.Items[Array.IndexOf(GridEngine.Categories,"학습")]).PerformClick();Assert(f.Day.Records.Single().Category=="학습"&&f.Day.Records.Single().Count==12,"category applies entire selection");}f.Quit();}});
   check("input: category assignment and plan copy retain typed scores without dialogs",()=>{var s=New();using(var f=new MainForm(new Store(Path.Combine(dir,"quick-copy.json")),s,true)){f.Show();Application.DoEvents();var selected=new CellSelection{Lane=1,First=51,Last=53};f.Board.SetSelection(selected);f.ApplyQuickScore(4);f.CopyPlanned(new PaletteRequest{Selection=selected,Item=f.GridPlan.Blocks.Single(x=>x.MealId=="b1")});Assert(f.Day.Records.Single().MealId=="b1"&&GridEngine.Total(f.Day)==12,"copy preserves 4*3");f.Board.SetSelection(new CellSelection{Lane=1,First=60,Last=65});f.ApplyQuickScore(2);f.ApplyCategory(f.Board.Selection,"작업");Assert(f.Day.Records.Where(x=>x.Category=="작업").Sum(x=>x.Score*x.Count)==12&&GridEngine.Total(f.Day)==24,"score then category");f.Quit();}});
  }
 }
}
